/*
 * LEADERBOARD STORE
 * -----------------
 * Works out of the box with zero setup: scores are kept in this browser.
 *
 * To make the leaderboard SHARED between every player, create a free
 * Supabase project (https://supabase.com), then paste your project URL
 * and anon public key below. That is all — the app switches over
 * automatically and falls back to local storage if the network fails.
 *
 * SQL to run once in the Supabase SQL editor:
 *
 *   create table scores (
 *     id bigint generated by default as identity primary key,
 *     name text not null,
 *     score int not null,
 *     total int not null,
 *     created_at timestamptz not null default now()
 *   );
 *   alter table scores enable row level security;
 *   create policy "anyone can read"   on scores for select using (true);
 *   create policy "anyone can insert" on scores for insert with check (true);
 */

const Store = (function () {
  'use strict';

  /* ---- paste your Supabase details here to share scores ---- */
  const REMOTE = {
    url: '',        // e.g. 'https://abcdefghijkl.supabase.co'
    anonKey: '',    // the "anon public" key
    table: 'scores'
  };
  /* ---------------------------------------------------------- */

  const KEY = 'tobi_scores_v2';
  const LIMIT = 100;
  let supabaseClient = null;
  let realtimeChannel = null;
  const listeners = new Set();

  function isRemote() {
    return Boolean(REMOTE.url && REMOTE.anonKey);
  }

  function ensureSupabase() {
    if (!isRemote()) return null;
    if (typeof window === 'undefined' || !window.supabase) return null;

    if (!supabaseClient) {
      supabaseClient = window.supabase.createClient(REMOTE.url, REMOTE.anonKey, {
        auth: {
          persistSession: false,
          autoRefreshToken: false
        }
      });
    }

    return supabaseClient;
  }

  function notifyListeners() {
    listeners.forEach(function (listener) {
      try {
        listener();
      } catch (err) {
        console.warn('[leaderboard] live listener failed', err);
      }
    });
  }

  function endpoint(path) {
    return REMOTE.url.replace(/\/+$/, '') + '/rest/v1/' + REMOTE.table + path;
  }

  function headers(extra) {
    return Object.assign(
      {
        apikey: REMOTE.anonKey,
        Authorization: 'Bearer ' + REMOTE.anonKey
      },
      extra || {}
    );
  }

  function readLocal() {
    try {
      const raw = localStorage.getItem(KEY);
      const rows = raw ? JSON.parse(raw) : [];
      return Array.isArray(rows) ? rows : [];
    } catch (err) {
      return [];
    }
  }

  function writeLocal(rows) {
    try {
      localStorage.setItem(KEY, JSON.stringify(rows.slice(0, 200)));
    } catch (err) {
      /* storage full or disabled — nothing we can do */
    }
  }

  function sortRows(rows) {
    return rows.slice().sort(function (a, b) {
      if (b.score !== a.score) return b.score - a.score;
      return new Date(a.created_at) - new Date(b.created_at);
    });
  }

  function normalise(rows) {
    return sortRows(rows).slice(0, LIMIT).map(function (r) {
      return {
        name: String(r.name || 'Anonymous').slice(0, 20),
        score: Number(r.score) || 0,
        total: Number(r.total) || 0,
        created_at: r.created_at || new Date().toISOString()
      };
    });
  }

  function subscribe(listener) {
    if (typeof listener !== 'function') return function () {};
    const client = ensureSupabase();
    if (!client) return function () {};

    listeners.add(listener);

    if (!realtimeChannel) {
      realtimeChannel = client.channel('scores-live');
      realtimeChannel.on(
        'postgres_changes',
        { event: '*', schema: 'public', table: REMOTE.table },
        function () {
          notifyListeners();
        }
      );
      realtimeChannel.subscribe();
    }

    return function unsubscribe() {
      listeners.delete(listener);
      if (!listeners.size && realtimeChannel) {
        client.removeChannel(realtimeChannel);
        realtimeChannel = null;
      }
    };
  }

  async function list() {
    if (!isRemote()) return normalise(readLocal());

    try {
      const res = await fetch(
        endpoint('?select=name,score,total,created_at&order=score.desc,created_at.asc&limit=' + LIMIT),
        { headers: headers() }
      );
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const rows = await res.json();
      if (!Array.isArray(rows)) throw new Error('Unexpected response');
      return normalise(rows);
    } catch (err) {
      console.warn('[leaderboard] shared board unavailable, using this device.', err);
      return normalise(readLocal());
    }
  }

  async function add(entry) {
    const row = {
      name: String(entry.name || 'Anonymous').slice(0, 20),
      score: Number(entry.score) || 0,
      total: Number(entry.total) || 0,
      created_at: new Date().toISOString()
    };

    if (!isRemote()) {
      const local = readLocal();
      local.unshift(row);
      writeLocal(local);
      return { shared: false, row: row };
    }

    try {
      const res = await fetch(endpoint(''), {
        method: 'POST',
        headers: headers({
          'Content-Type': 'application/json',
          Prefer: 'return=minimal'
        }),
        body: JSON.stringify({
          name: row.name,
          score: row.score,
          total: row.total
        })
      });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      notifyListeners();
      return { shared: true, row: row };
    } catch (err) {
      console.warn('[leaderboard] could not save to the shared board.', err);
      // Keep the score on this device so it is not lost.
      const local = readLocal();
      local.unshift(row);
      writeLocal(local);
      return { shared: false, row: row };
    }
  }

  return { list: list, add: add, subscribe: subscribe, isRemote: isRemote, LIMIT: LIMIT };
})();
